import {distance,hit} from './enemies.js';
export const HEROES={warden:{name:'Aldric',title:'The Last Warden',sprite:97,unlock:0,hp:180,damage:10,range:17,rate:.8,q:'Ground slam',w:'Rallying banner'},witch:{name:'Mora',title:'The Frost Witch',sprite:84,unlock:3,hp:120,damage:14,range:65,rate:1.1,q:'Ice nova',w:'Winter standard'},hunter:{name:'Silas',title:'The Bounty Hunter',sprite:111,unlock:6,hp:145,damage:18,range:58,rate:1.2,q:'Deadeye volley',w:'Wanted banner'},bunny:{name:'Bonnie',title:'The Bombshell',sprite:99,unlock:7,hp:150,damage:22,range:52,rate:1.5,q:'Cluster bombs',w:'Powder banner'}};
export function createHero(g){const data=HEROES[g.save.hero];const level=1+Math.floor(g.save.heroXP/60),hp=data.hp+level*5+g.meta.heroes*20;return {...data,type:g.save.hero,x:338,y:195,target:{x:338,y:195},hp,maxHP:hp,armor:.15,attack:0,q:0,w:0,respawn:0,level};}
export function ability(g,key,p){if(g.paused||g.outcome)return false;const h=g.hero;if(h.hp<=0||h[key]>0)return false;if(key==='q'){const target=p||h,r=h.type==='hunter'?85:48;for(const e of g.enemies)if(distance(target,e)<r&&(!e.air||h.type==='hunter')){hit(g,e,h.type==='bunny'?100:70,'true',h.type);if(h.type==='witch')e.slow=6;}g.effects.push({type:'ring',x:target.x,y:target.y,r,life:.65,color:h.type==='witch'?'#a2d9e2':'#e4be77'});g.shake=3;h.q=22;g.audio.play('blast');}else{g.banner={x:h.x,y:h.y,life:9};h.w=32;g.audio.play('horn');}return true;}
export function updateHero(g,dt){const h=g.hero;if(g.banner&&(g.banner.life-=dt)<=0)g.banner=null;h.q=Math.max(0,h.q-dt);h.w=Math.max(0,h.w-dt);if(h.hp<=0){h.blockedBy=null;h.respawn-=dt;if(h.respawn<=0){h.hp=h.maxHP;h.x=h.target.x;h.y=h.target.y;}return;}const d=distance(h,h.target);if(d>3){h.blockedBy=null;h.x+=(h.target.x-h.x)/d*46*dt;h.y+=(h.target.y-h.y)/d*46*dt;}h.attack-=dt;const e=g.enemies.find(e=>e.hp>0&&(!e.air||h.range>30)&&distance(h,e)<h.range);if(e&&h.attack<=0){const damage=h.damage*(1+g.meta.heroes*.1+h.level*.03);if(h.type==='bunny'){for(const other of g.enemies)if(distance(other,e)<22&&!other.air)hit(g,other,damage,'physical',h.type);g.effects.push({type:'ring',x:e.x,y:e.y,r:22,life:.35,color:'#eeb686'});}else hit(g,e,damage,h.type==='witch'?'magic':'physical',h.type);if(h.type==='witch')e.slow=2;h.attack=h.rate;g.effects.push({type:'bolt',x:h.x,y:h.y-8,tx:e.x,ty:e.y-5,life:.12,color:'#edd4a0'});}if(!e)h.hp=Math.min(h.maxHP,h.hp+dt*2);}
